command:
if (!game.user.isGM) return ui.notifications.warn('Reactivate Unit(s) is GM-only.');

const selected = canvas.tokens?.controlled ?? [];
const units = selected.filter(token => token.actor?.type === 'Character');
if (!units.length) return ui.notifications.warn('Select one or more Character units first.');

const planning = units.filter(token => token.actor.system?.turn?.movementPlanning === true);
const ready = units.filter(token => token.actor.system?.turn?.movementPlanning !== true);

const TURN_RESET = {
  'system.turn.actionAvailable': true,
  'system.turn.bonusActionAvailable': true,
  'system.turn.movementAvailable': true,
  'system.turn.movementSpent': 0,
  'system.turn.extraActionUsed': false,
  'system.turn.traded': false,
  'system.turn.continuationPending': '',
  'system.turn.continuationRequestId': ''
};

const restored = [];
const failures = [];

for (const token of ready) {
  const actor = token.actor;
  const turn = actor.system?.turn ?? {};
  const spent = [
    turn.actionAvailable === true ? null : 'action',
    turn.bonusActionAvailable === true ? null : 'bonus',
    turn.movementAvailable === true ? null : 'movement'
  ].filter(Boolean);
  try {
    await actor.update(TURN_RESET);
    restored.push({
      unit: actor.name,
      restored: spent.length ? spent.join(', ') : 'already reactive',
      movementSpent: Number(turn.movementSpent) || 0
    });
  } catch (err) {
    failures.push({ unit: actor.name, error: err.message });
    console.error(`emblem-rpg | Reactivate Unit(s) failed for ${actor.name}:`, err);
  }
}

console.group(`emblem-rpg | Reactivate Unit(s) — ${restored.length} unit(s) reactivated`);
if (restored.length) console.table(restored);
if (planning.length) console.table(planning.map(token => ({ unit: token.actor.name, skipped: 'movement plan open' })));
if (failures.length) console.table(failures);
console.groupEnd();

const held = planning.length ? ` ${planning.length} skipped with an open movement plan.` : '';
if (failures.length) {
  ui.notifications.error(`Reactivated ${restored.length} unit(s); ${failures.length} failed, see console.${held}`);
} else if (!restored.length) {
  ui.notifications.warn(`No unit reactivated.${held}`);
} else {
  ui.notifications.info(`Reactivated ${restored.length} unit(s).${held}`);
}
